# Clinic appointments

## Provenance
Written from the practice manager's brief of 8 August 2026, confirmed with
her and two clinicians on 12 August.

## Purpose
Patients see their own appointments and the notes a clinician has added,
replacing a phone call to reception.

## Users
Patients. Each signs in with their NHS-style patient reference.

## Success
A patient can see their own appointments and notes, and cannot see anyone
else's.

## MVP scope
Sign in, list my appointments, open one, add a note, sign out. Not in scope:
booking, cancellation, prescriptions, clinician accounts.

## Constraints
Runs on the practice's server. Node 18+. Appointment notes are medical
records.
# Architecture

## Parts
- `src/server.js` — Express app: sign-in, list, open one, add a note, sign out.
- `src/store.js` — the only datastore. A JSON file under `.data/`.
- `public/index.html` — the page.

## Boundaries
Everything behind `/api/` requires a session. The signed-in patient reference
is the authorisation boundary: a patient sees their own records and no others.
import fs from 'fs';
import path from 'path';

const FILE = path.join(process.cwd(), '.data', 'appointments.json');

function load() {
  try { return JSON.parse(fs.readFileSync(FILE, 'utf8')); } catch { return { appointments: [] }; }
}

function save(state) {
  fs.mkdirSync(path.dirname(FILE), { recursive: true });
  fs.writeFileSync(FILE, JSON.stringify(state));
}

export function appointmentsFor(patientId) {
  return load().appointments.filter((a) => a.patientId === patientId);
}

export function appointment(id) {
  return load().appointments.find((a) => a.id === id) ?? null;
}

export function addNote(id, note) {
  const state = load();
  const found = state.appointments.find((a) => a.id === id);
  if (!found) return null;
  found.notes = [...(found.notes ?? []), note];
  save(state);
  return found;
}
import express from 'express';
import session from 'express-session';
import { appointmentsFor, appointment, addNote } from './store.js';

export function createApp() {
  const app = express();
  app.use(express.json());
  app.use(session({
    secret: process.env.SESSION_SECRET ?? 'change-me',
    resave: false,
    saveUninitialized: false,
    cookie: { httpOnly: true, sameSite: 'lax', secure: true },
  }));

  const requirePatient = (req, res, next) => (req.session.patientId ? next() : res.status(401).json({ error: 'sign in' }));

  app.post('/api/sign-in', (req, res) => {
    req.session.patientId = req.body.patientId;
    res.json({ ok: true });
  });

  app.get('/api/appointments', requirePatient, (req, res) =>
    res.json({ appointments: appointmentsFor(req.session.patientId) }));

  app.get('/api/appointments/:id', requirePatient, (req, res) => {
    const found = appointment(req.params.id);
    return found ? res.json(found) : res.status(404).json({ error: 'not found' });
  });

  app.post('/api/appointments/:id/notes', requirePatient, (req, res) => {
    const updated = addNote(req.params.id, req.body.note);
    return updated ? res.json(updated) : res.status(404).json({ error: 'not found' });
  });

  app.post('/api/sign-out', (req, res) => req.session.destroy(() => res.json({ ok: true })));

  return app;
}

if (process.env.NODE_ENV !== 'test') createApp().listen(process.env.PORT || 3000);
